<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{AdmissionPeriod,AdmissionWave,StudentApplication}; use App\Services\ApplicationStatusService; use Illuminate\Http\Request;
class ApplicationController extends Controller { public function index(Request $r){
 $r->validate(['search'=>'nullable|string|max:255','period'=>'nullable|integer|exists:admission_periods,id','wave'=>'nullable|integer|exists:admission_waves,id','status'=>'nullable|in:draft,submitted,under_review,revision,verified,accepted,rejected','sort'=>'nullable|in:newest,oldest,name_asc,name_desc']);
 $q=StudentApplication::with(['user','studentProfile','wave','period'])
 ->when($r->status,fn($x,$v)=>$x->where('status',$v))
 ->when($r->period,fn($x,$v)=>$x->where('admission_period_id',$v))
 ->when($r->wave,fn($x,$v)=>$x->where('admission_wave_id',$v))
 ->when($r->search,function($x,$v){$x->where(function($group)use($v){$group->where('registration_number',\App\Support\DatabaseSearch::operator(),"%$v%")->orWhereHas('user',fn($u)=>$u->where('name',\App\Support\DatabaseSearch::operator(),"%$v%")->orWhere('email',\App\Support\DatabaseSearch::operator(),"%$v%"))->orWhereHas('studentProfile',fn($p)=>$p->where('full_name',\App\Support\DatabaseSearch::operator(),"%$v%")->orWhere('nik',\App\Support\DatabaseSearch::operator(),"%$v%"));});});
 $sort=$r->sort??'newest';
 $q=match($sort){'oldest'=>$q->oldest(),'name_asc'=>$q->join('student_profiles','student_profiles.student_application_id','=','student_applications.id')->orderBy('student_profiles.full_name')->select('student_applications.*'),'name_desc'=>$q->join('student_profiles','student_profiles.student_application_id','=','student_applications.id')->orderByDesc('student_profiles.full_name')->select('student_applications.*'),default=>$q->latest()};
 return view('admin.applications.index',['items'=>$q->paginate(15)->withQueryString(),'periods'=>AdmissionPeriod::all(),'waves'=>AdmissionWave::all()]);
} public function show(StudentApplication $application){$application->load(['user','studentProfile','parentProfile','documents','period','wave','statusHistories.changedBy']);return view('admin.applications.show',compact('application'));} public function transition(Request $r,StudentApplication $application,ApplicationStatusService $service){$data=$r->validate(['to'=>'required|in:under_review,revision,verified,accepted,rejected','note'=>'nullable|string|max:2000']);$service->transition($application,$data['to'],$data['note']??null,$r->user()->id);return back()->with('success','Status pendaftaran berhasil diperbarui.');} }
